using HRIS.Api.Common; using HRIS.Api.Data; using HRIS.Api.Exceptions; using HRIS.Api.Models; using HRIS.Api.Models.Enums;
namespace HRIS.Api.Services; public class ParkingApprovalHandler:IApprovalHandler { private readonly AppDbContext _db; public ParkingApprovalHandler(AppDbContext db)=>_db=db; public string RequestType=>ApprovalRequestTypes.Parking; public async Task OnCompletedAsync(ApprovalRequest request,ApprovalRequestStatus finalStatus){var x=await _db.ParkingRegistrations.FindAsync(request.RequestRefId)??throw new NotFoundException("Registrasi parkir tidak ditemukan.");x.Status=finalStatus switch{ApprovalRequestStatus.Approved=>"Approved",ApprovalRequestStatus.Rejected=>"Rejected",ApprovalRequestStatus.Cancelled=>"Cancelled",_=>x.Status};await _db.SaveChangesAsync();} }
